const char* getNamedResource (const char* resourceNameUTF8, int& numBytes);
const char* getNamedResource (const char* resourceNameUTF8, int& numBytes)
{
    unsigned int hash = 0;

    if (resourceNameUTF8 != nullptr)
        while (*resourceNameUTF8 != 0)
            hash = 31 * hash + (unsigned int) *resourceNameUTF8++;

    switch (hash)
    {
        case 0x22f6bff2:  numBytes = 256419; return BGr_svg;
        case 0x22316aa9:  numBytes = 2532263; return BGd_png;
        case 0x4a0ed949:  numBytes = 1567; return B16f_png;
        case 0x4a7f9551:  numBytes = 1567; return B16n_png;
        case 0xe48f44ea:  numBytes = 404428; return E32d_png;
        case 0x5b3c327f:  numBytes = 195548; return P32d_png;
        case 0x9a5f817a:  numBytes = 371366; return P48d_png;
        case 0xc14e44bd:  numBytes = 1436; return R12f_png;
        case 0xc1bf00c5:  numBytes = 1116; return R12n_png;
        default: break;
    }

    numBytes = 0;
    return nullptr;
}

